package com.alpha0.app.game

import java.io.File
import java.security.MessageDigest
import java.util.concurrent.CancellationException
import org.junit.Assert.*
import org.junit.Test

/** Generated bytes and pins are test-only, never official game assets. */
class GameBinaryEvidenceTest {
    @Test fun exactSizeAndDigestMustMatchAndUnknownNeverPromotes() {
        val file = File.createTempFile("sentinel-asset-test", ".apk")
        try {
            file.writeText("locally synthetic test APK bytes")
            val digest = MessageDigest.getInstance("SHA-256").digest(file.readBytes())
                .joinToString("") { "%02x".format(it.toInt() and 0xff) }
            val pins = listOf(GameBinaryEvidence.AssetPin(
                GameBinaryEvidence.Status.MATCHED_GITHUB_ANDROID, file.length(), digest,
            ))
            val signer = "b".repeat(64)
            fun inspect(sha: String? = signer, version: String = "4.0.2", code: Long = 922,
                assets: List<GameBinaryEvidence.AssetPin> = pins) =
                GameBinaryEvidence.inspect(file, version, code, sha, assets)
            assertEquals(GameBinaryEvidence.Status.MATCHED_GITHUB_ANDROID, inspect())
            assertEquals(GameBinaryEvidence.Status.UNSUPPORTED_VERSION, inspect(version = "4.0.1"))
            assertEquals(GameBinaryEvidence.Status.UNSUPPORTED_VERSION, inspect(code = 921))
            assertEquals(GameBinaryEvidence.Status.UNAVAILABLE, inspect(sha = null))
            assertEquals(GameBinaryEvidence.Status.UNAVAILABLE, inspect(sha = "bad"))
            assertEquals(GameBinaryEvidence.Status.OTHER_OR_SPLIT,
                inspect(assets = pins.map { it.copy(sha256 = "c".repeat(64)) }))
            assertEquals(GameBinaryEvidence.Status.OTHER_OR_SPLIT,
                inspect(assets = pins.map { it.copy(size = it.size + 1) }))
            file.appendText("tampered")
            assertEquals(GameBinaryEvidence.Status.OTHER_OR_SPLIT, inspect())
        } finally {
            file.delete()
        }
    }

    @Test fun cancellableAndUnreadableLocalInputFailClosed() {
        val file = File.createTempFile("sentinel-asset-cancel", ".apk")
        try {
            file.writeText("fixture")
            val signer = "a".repeat(64)
            val digest = MessageDigest.getInstance("SHA-256").digest(file.readBytes())
                .joinToString("") { "%02x".format(it.toInt() and 0xff) }
            val pins = listOf(GameBinaryEvidence.AssetPin(
                GameBinaryEvidence.Status.MATCHED_GITHUB_GPLAY, file.length(), digest,
            ))
            assertThrows(CancellationException::class.java) {
                GameBinaryEvidence.inspect(file, "4.0.2", 922, signer, pins) {
                    throw CancellationException()
                }
            }
            assertEquals(GameBinaryEvidence.Status.MATCHED_GITHUB_GPLAY,
                GameBinaryEvidence.inspect(file, "4.0.2", 922, signer, pins))
            assertEquals(GameBinaryEvidence.Status.UNAVAILABLE,
                GameBinaryEvidence.inspect(File(file.path + ".missing"), "4.0.2", 922, signer, pins))
        } finally {
            file.delete()
        }
    }
}
